import { Session } from './src/session.js';

const host = queryFn => ({ queryFn, timers: { schedule: fn => queueMicrotask(fn) } });
const settle = () => new Promise(resolve => setImmediate(resolve));

let calls = 0;
const offline = new Session(host(({ signal }) => { calls++; assert.equal(signal.aborted, false); return 'stop'; }), { online: false });
const departed = offline.subscribe('central', { networkMode: 'online', refetchOnReconnect: true });
assert.deepEqual(offline.snapshot('central'), { status: 'pending', fetchStatus: 'paused', data: null });
offline.unsubscribe(departed);
offline.online(true);
await settle();
assert.equal(calls, 0);
assert.deepEqual(offline.snapshot('central'), { status: 'pending', fetchStatus: 'idle', data: null });

let resolve;
const retained = new Session(host(() => new Promise(done => { resolve = done; })));
const observer = retained.subscribe('central');
retained.unsubscribe(observer);
resolve('cached stop');
await settle();
assert.deepEqual(retained.snapshot('central'), { status: 'success', fetchStatus: 'idle', data: 'cached stop' });

let sharedCalls = 0;
const shared = new Session(host(() => { sharedCalls++; return 'stop'; }), { online: false });
const first = shared.subscribe('central');
const second = shared.subscribe('central');
